"""Package only selected task sources/metadata; no scientific execution or index edit."""
import hashlib,json
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]
TASK='NEURAL-092'
EXCLUDE={'delivery_manifest.json','GENERATED_CHECKS.json','ASSEMBLE.json','CHECK.json','source_head.py','block_census.py','inspect_schema.py','inspect_remaining.py','inspect_pupil.py'}
PUBLIC={'ALLENSDK_LICENSE.txt','ENVIRONMENT.md','PROTOCOL.json','PUBLIC_INTERFACE.json','CANDIDATE_ALLOWLIST.json','TASK.md','requirements.txt','submission.schema.json','io_contract.py','packet_io.py'}
files=[]
for path in sorted(HERE.glob('*')):
 if not path.is_file() or path.name in EXCLUDE or path.suffix not in ('.py','.json','.md','.txt'):continue
 raw=path.read_bytes();private=path.name not in PUBLIC
 files.append({'source':str(path.relative_to(ROOT)),'target':('private/' if private else 'public/')+path.name,'visibility':'private' if private else 'public','role':'source_metadata' if path.name=='ROSTER.json' else 'source','bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()})
def component(status,targets,blockers=[]):return {'status':status,'targets':targets,'blockers':blockers}
gaps=['All32 authenticated full NWB bodies (80,462,809,684B) are absent; only exact object sizes/URLs/opaque ETags, stimulus block metadata and bounded schemas held.','No authentic complete public/private task packet or full-panel native-schema/runtime compatibility has been established.','No authenticated per-unit observation coverage; complete-window rates remain a stated assumption, not verified silence.','No fitted method-matched state-only comparator or qualified explanatory/predictive gain; no model/agent or scientific evaluation.','Scorer CPU/memory over fullpanel unqualified; exact rational/log pooling can be expensive and declared caps refuse, never shrink.']
scientific_scope='Static-grating family response-rate extrapolation in the same recorded units; fixed FIT mean-rate comparator; no cross-mouse neuron transfer or qualified beyond-state gain.' if TASK.endswith('091') else 'Observed-data stimulus-matched running/pupil state-by-area reconstruction and all15 FIT/QC-matched area-pair sensitivities; no causal effect or qualified explanatory gain.'
obj={'schema':'neurobench_delivery_v1','task_ids':[TASK],'files':files,'components':{'task_contract':component('complete',['public/TASK.md','public/PROTOCOL.json']),'submission_schema':component('complete',['public/submission.schema.json','public/PUBLIC_INTERFACE.json','private/private.schema.json']),'scorer':component('complete',['private/score.py','private/analysis.py','private/state_core.py','public/packet_io.py','public/io_contract.py']),'data':{'status':'partial','mode':'frozen_full_cohort_acquisition_and_deterministic_preparation_recipe','targets':['private/ROSTER.json','private/PROVISION.md','private/acquire.py','private/prepare.py','private/nwb_input.py','private/projection.py'],'blockers':gaps},'dependencies':component('complete',['public/requirements.txt','public/ENVIRONMENT.md'])},'scope':{'implemented':scientific_scope,'cohort':{'selected_sessions':32,'selected_mice':32,'other_protocol_dispositions':26,'source_gaze_present':26,'source_gaze_absent':6},'canonical_beyond_state_or_gain_satisfied':False,'all_input_sources_present':False,'models_fitted':0,'scientific_scores_computed':0,'authentic_neural_or_behavior_arrays_read':False},'source_only':True,'historical_qualification':{'declared_status':'canonical specification_only','not_reassessed':True},'limitations':gaps+['Whole-recording sorting/QC and filtered pupil are transductive. Running/pupil associations observational, coarse matching not causal.','Each neuron belongs only to its native session; mouse genotype cannot identify genetic unit class.','No submission-ready, SOTA, biological effect or research-qualified result is claimed.'],'distribution':{'local_use':'Authorized recipe/source construction; authentic complete source objects and prepared packets absent.','public_redistribution':'Separate Allen source/data terms; no rights clearance asserted. Missing data status is not inferred from redistribution uncertainty.'}}
body=(json.dumps(obj,indent=2)+'\n').encode();(HERE/'delivery_manifest.json').write_bytes(body);print(json.dumps({'task':TASK,'files':len(files),'source_bytes':sum(x['bytes'] for x in files),'descriptor_bytes':len(body),'sha256':hashlib.sha256(body).hexdigest()}))
